import { useMemo, useId } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from variableColorLine ----
type ConditionKey = 'CLR' | 'FEW' | 'SCT' | 'BKN' | 'OVC';

type SkyObservation = { date: Date; temperature: number; condition: ConditionKey };

/** METAR sky-cover codes, lightened from the Observable palette for the dark gallery. */
const CONDITIONS: { key: ConditionKey; label: string; color: string }[] = [
  { key: 'CLR', label: 'Clear', color: '#00bfff' },
  { key: 'FEW', label: 'Few clouds', color: '#87cefa' },
  { key: 'SCT', label: 'Scattered', color: '#c3ddea' },
  { key: 'BKN', label: 'Broken', color: '#a9aeb3' },
  { key: 'OVC', label: 'Overcast', color: '#71767b' }
];

const HOURS = 240; // ten days of hourly observations

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const classify = (cover: number): ConditionKey =>
  cover < 0.12 ? 'CLR' : cover < 0.32 ? 'FEW' : cover < 0.55 ? 'SCT' : cover < 0.8 ? 'BKN' : 'OVC';

const random = seededRandom(20260813);

/** Cover reverts to a slow synoptic swing, so conditions arrive in spells rather than flicker. */
const skyObservations: SkyObservation[] = (() => {
  let cover = 0.05;
  return Array.from({ length: HOURS }, (_, hour) => {
    const synoptic = 0.42 + 0.34 * Math.sin((hour / HOURS) * 2 * Math.PI - 1.3);
    cover += (synoptic - cover) * 0.06 + (random() - 0.5) * 0.15;
    cover = Math.min(1, Math.max(0, cover));
    const diurnal = -Math.cos(((hour % 24) / 24) * 2 * Math.PI);
    const frontPassage = 7 * Math.sin((hour / HOURS) * Math.PI);
    return {
      date: new Date(Date.UTC(2026, 2, 1, hour)),
      // Cloud cover damps the daytime swing, so color and height move together.
      temperature: 48 + frontPassage + 15 * diurnal * (1 - 0.6 * cover) + (random() - 0.5) * 2,
      condition: classify(cover)
    };
  });
})();

const MARGIN = { top: 40, right: 20, bottom: 36, left: 52 };
const LEGEND_ITEM_WIDTH = 96;

/**
 * Observations in chronological order, plus the condition codes they draw from: a caller
 * who swaps the observations must swap the codes too, since each carries its own colour.
 */
export type Data = {
  observations: { date: Date; temperature: number; condition: string }[];
  conditions: { key: string; label: string; color: string }[];
};

const DEMO: Data = { observations: skyObservations, conditions: CONDITIONS };

export default function VariableColorLine({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const gradientId = useId();
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain(data.conditions.map((c) => c.key))
        .range(data.conditions.map((c) => c.color))
        .unknown('var(--muted)'),
    [data]
  );

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data.observations, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data.observations, (d) => d.temperature) as [number, number])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const path = useMemo(
    () =>
      d3
        .line<Data['observations'][number]>()
        .x((d) => x(d.date))
        .y((d) => y(d.temperature))
        .curve(d3.curveStep)(data.observations) ?? '',
    [data, x, y]
  );

  // One stop pair per run of identical conditions: the color holds flat across a run and
  // blends only over the single interval between runs, which is what a per-point stop list does.
  const stops = useMemo(() => {
    const rows = data.observations;
    const out: { offset: number; color: string }[] = [];
    let start = 0;
    for (let i = 1; i <= rows.length; i += 1) {
      if (i === rows.length || rows[i].condition !== rows[start].condition) {
        const stopColor = color(rows[start].condition);
        out.push({ offset: x(rows[start].date) / innerWidth, color: stopColor });
        out.push({ offset: x(rows[i - 1].date) / innerWidth, color: stopColor });
        start = i;
      }
    }
    return out;
  }, [data, x, innerWidth, color]);

  const xTicks: Tick[] = useMemo(
    () => x.ticks(6).map((v) => ({ value: d3.utcFormat('%b %d')(v), offset: x(v) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: `${v}°F`, offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  const showLegend = innerWidth >= data.conditions.length * LEGEND_ITEM_WIDTH;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Line chart of hourly temperature, stroked with a gradient encoding sky condition">
      <defs>
        <linearGradient id={gradientId} gradientUnits="userSpaceOnUse" x1={0} x2={innerWidth}>
          {stops.map((stop, i) => (
            <stop key={i} offset={stop.offset} stopColor={stop.color} />
          ))}
        </linearGradient>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {showLegend &&
          data.conditions.map((condition, i) => (
            <g key={condition.key} transform={`translate(${i * LEGEND_ITEM_WIDTH},-28)`}>
              <rect width={11} height={11} rx={2} fill={condition.color} />
              <text x={16} y={9} fill="var(--muted)" fontSize={11}>
                {condition.label}
              </text>
            </g>
          ))}
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <path d={path} fill="none" stroke={`url(#${gradientId})`} strokeWidth={2}
              strokeLinejoin="round" strokeLinecap="round" />
      </g>
    </svg>
  );
}
